//! The helper's table of the files the page only shows: the root-owned
//! `read_only` entries of the config file catalog as Rust constants. The
//! helper links no TOML, so the table is a checked-in file, and a fetch
//! hands out nothing outside it and the write table.

#[cfg(test)]
mod tests;

use std::fs;

use toolbox_catalog::{ConfigFileCatalog, ConfigSection};
use toolbox_plan::ConfigEntryLocation;

use crate::catalogs::SOURCE_DIR;
use crate::{Failure, flags, root};

/// The generated file, relative to the repository root.
pub const TARGET: &str = "crates/plan/src/config_file/readable.rs";
/// rustfmt's `array_width` and `max_width`: the text must stay as rustfmt
/// leaves it, or `nix fmt` and `--check` would fight over it.
const ARRAY_WIDTH: usize = 60;
const MAX_WIDTH: usize = 100;

#[derive(Debug, Default, PartialEq, Eq)]
pub struct Readable {
    pub files: Vec<String>,
    pub folders: Vec<String>,
}

/// The read-only root-owned entries of `catalog`, sorted, as the helper
/// looks them up with a binary search.
pub fn readable(catalog: &ConfigFileCatalog) -> Readable {
    let mut table = Readable::default();

    for entry in catalog
        .sections()
        .iter()
        .flat_map(ConfigSection::entries)
        .filter(|entry| entry.is_read_only())
    {
        let ConfigEntryLocation::Root(path) = entry.location() else {
            continue;
        };

        let list = if entry.is_directory() {
            &mut table.folders
        } else {
            &mut table.files
        };

        list.push(path.as_str().to_owned());
    }

    table.files.sort();
    table.folders.sort();
    table
}

pub fn render(table: &Readable) -> String {
    let files = constant(
        "/// The read-only root-owned files of the catalog, sorted.\n",
        "READABLE_CONFIG_FILES",
        &table.files,
    );

    let folders = constant(
        "/// The read-only root-owned folders of the catalog (`directory = true`),\n\
         /// sorted. The page lists their regular files one level deep, so a fetch\n\
         /// may name any file directly in one of them.\n",
        "READABLE_CONFIG_FOLDERS",
        &table.folders,
    );

    format!(
        "//! Generated by `cargo xtask catalog-readable` from the `read_only` entries\n\
         //! of {SOURCE_DIR}/config-files.toml. Do not edit: the helper links no TOML,\n\
         //! so the table is checked in, and `cargo xtask catalog-readable --check`\n\
         //! fails when it is stale.\n\
         \n\
         {files}\n\
         {folders}"
    )
}

/// One `pub const` array in the layout rustfmt gives it: on one line
/// while it fits, else one item per line.
fn constant(docs: &str, name: &str, items: &[String]) -> String {
    let quoted: Vec<String> = items.iter().map(|item| format!("{item:?}")).collect();
    let head = format!("pub const {name}: [&str; {}] = ", items.len());
    let inline = format!("[{}]", quoted.join(", "));

    let array = if inline.len() <= ARRAY_WIDTH && head.len() + inline.len() < MAX_WIDTH {
        inline
    } else {
        let lines = quoted.iter().fold(String::new(), |mut lines, item| {
            lines.push_str("    ");
            lines.push_str(item);
            lines.push_str(",\n");
            lines
        });

        format!("[\n{lines}]")
    };

    format!("{docs}{head}{array};\n")
}

/// Writes the table, or with `--check` fails when the checked-in one
/// differs from what it would write.
pub fn catalog_readable(args: &[String]) -> Result<String, Failure> {
    let check = !flags(args, &["--check"]).ok_or(Failure::Usage)?.is_empty();

    let catalog = ConfigFileCatalog::load(&root().join(SOURCE_DIR))
        .map_err(|error| Failure::Problems(vec![error.to_string()]))?;

    let table = readable(&catalog);
    let text = render(&table);
    let target = root().join(TARGET);
    let current = fs::read_to_string(&target).unwrap_or_default();

    if current != text {
        if check {
            return Err(Failure::Problems(vec![format!(
                "{TARGET} is out of date: run `cargo xtask catalog-readable`"
            )]));
        }

        fs::write(&target, text)
            .map_err(|error| Failure::Problems(vec![format!("cannot write {TARGET}: {error}")]))?;
    }

    Ok(format!(
        "{} read-only files and {} read-only folders in {TARGET}",
        table.files.len(),
        table.folders.len()
    ))
}
